(function(){async function u(t){window.__infiniteDisabled=!0;n.innerHTML='<div class="text-center py-5 w-100">  <div class="spinner-border text-primary" role="status">    <span class="visually-hidden">Загрузка...<\/span>  <\/div><\/div>';try{const u="/Catalog/Search?query="+encodeURIComponent(t),i=await fetch(u);if(!i.ok)throw new Error("HTTP "+i.status);const r=await i.text();n.innerHTML=r.trim()?r:'<div class="alert alert-info w-100">Ничего не найдено<\/div>'}catch(i){n.innerHTML='<div class="alert alert-danger w-100">Ошибка поиска. Попробуйте ещё раз.<\/div>';console.error("Search error:",i)}}async function f(){n.innerHTML='<div class="text-center py-5 w-100">  <div class="spinner-border text-primary" role="status"><\/div><\/div>';try{const t=await fetch("/Catalog/Search");if(!t.ok)throw new Error("HTTP "+t.status);const i=await t.text();n.innerHTML=i.trim()?i:'<div class="alert alert-info w-100">Ничего не найдено<\/div>'}catch(t){n.innerHTML='<div class="alert alert-danger w-100">Ошибка загрузки. Попробуйте ещё раз.<\/div>';console.error(t)}}const t=document.getElementById("searchInput"),n=document.getElementById("catalogGrid");if(t&&n){const i=sessionStorage.getItem("catalogSearch");i&&i.trim().length>=2&&(t.value=i,u(i.trim()));let r;t.addEventListener("input",function(){sessionStorage.setItem("catalogSearch",t.value);clearTimeout(r);const n=t.value.trim();if(n.length<2){r=setTimeout(function(){f()},300);return}r=setTimeout(function(){u(n)},300)})}})();